def parse_fault_segment(fields):
    """校验并规范化单个故障段除 id 外的字段（k,a,z,v）：k ∈ D/F/S，
    a,z,v ∈ [0,10^9] 非 bool 整数且 a<z，D 须 v=0、F/S 须 v>0；
