        fail(EXIT_INPUT, "INPUT")
    a = parse_fault_num(fields["a"])
    z = parse_fault_num(fields["z"])
    v = parse_fault_num(fields["v"])
    if not a < z:
        fail(EXIT_INPUT, "INPUT")
    # D（不可用）须 v=0；F（抖动）/S（慢）须 v>0。
    if k == "D":
        if v != 0:
            fail(EXIT_INPUT, "INPUT")
    elif v == 0:
        fail(EXIT_INPUT, "INPUT")
    return k, a, z, v


